import json, os, sys
from functools import cache, wraps
from inspect import Parameter, Signature, signature
from fastcore.all import L
from fastcore.script import anno_parser
from .core import Vault
from . import acquire, ask, code, extract   # noqa: F401; these patch the Vault methods the CLI exposes

# %% ../nbs/04_cli.ipynb #11ed4c4a
CMDS = ('stats search sections context ask explain read related toc map topic_tree show_topics sources doc document shelves '
        'elsewhere '
        'grab url web crawl arxiv pdf youtube github gh_file add_file add_dir add_tree note connect forget '
        'apis harvest add_records watch watches unwatch pause poll schedule jobs retry_job index_code code_search symbol '
        'where_to_add grep federate drop_shelf categorize categorize_all doctypes of_type ner reshelf '
        'extract '
        'extract_all ask_doc '
        'pii mark_pii mark_not_pii mark_noisy mark_noisy_many marks '
        'level set_level floor set_floor findings scan_pii accept_pii reject_pii reset_pii send_check sends '
        'suggest_noisy accept_noisy learn fit_noise use_noise '
        'read_doc pages reparse proofread changes accept reject edit_change undo_decision revert_page proof_md').split()

@cache
def vault(path:str=None) -> Vault:
    "The one vault every command uses: the file `$VISHALAKSHI_VAULT` names, else the default path."
    return Vault(path or os.getenv('VISHALAKSHI_VAULT') or None,
                 offline=bool(os.getenv('VISHALAKSHI_OFFLINE')))

def _spellable(p) -> bool:
    'Can this parameter be written on a command line? `self`, `**kw`, a test stand-in chat, the `stop` and `progress` callbacks and callable defaults cannot.'
    return (p.name not in ('self', 'chat', 'chats', 'local_chat', 'stop', 'progress') and p.kind is not Parameter.VAR_KEYWORD
            and not (p.default is not Parameter.empty and callable(p.default)))

def cmd(name:str, vault_fn=vault):
    "Turn a `Vault` method into a plain function of the arguments a command line can give, keeping their descriptions."
    f = getattr(Vault, name)
    g = wraps(f)(lambda **kw: getattr(vault_fn(), name)(**kw))
    ps = L(signature(f).parameters.values()).filter(_spellable)
    g.__signature__, g.__delwrap__ = Signature(ps), f
    g.__annotations__ = {p.name: p.annotation for p in ps if p.annotation is not Parameter.empty}
    return g


# %% ../nbs/04_cli.ipynb #f0a650d6
def jsonable(o):
    "Make a value JSON-friendly for `json.dumps`: sequences become lists, numpy scalars numbers, and anything else a string."
    if hasattr(o, '__iter__') and not isinstance(o, (str, bytes, dict)): return list(o)
    return o.item() if hasattr(o, 'item') else str(o)

def show(r):
    'Print a result: an answer as prose with its citations, anything else as JSON.'
    if isinstance(r, str): return print(r)
    if isinstance(r, dict) and 'answer' in r:
        print(r['answer'])
        # a code citation has no node_id: its handle is the path:line the hit came from
        for c in r.get('cited', []): print(f"  [{c['n']}] {c['breadcrumb']}  {c['node_id'] or c['source'] or ''}")
    else: print(json.dumps(r, indent=2, default=jsonable))

def main():
    "Run the `vishalakshi` command; `vishalakshi <cmd> --help` describes any subcommand."
    name = sys.argv[1].replace('-', '_') if len(sys.argv) > 1 else None
    if name not in CMDS:
        print(f"Usage: vishalakshi <cmd> [args]\n\n  {'  '.join(CMDS)}\n", file=sys.stderr)
        sys.exit(0 if name is None else 1)
    del sys.argv[1]
    f = cmd(name)
    kw = anno_parser(f, prog=f'vishalakshi {name}').parse_args().__dict__
    show(f(**{k: v for k, v in kw.items() if k not in ('pdb', 'xtra')}))
